CREATE TABLE truss.relationship_lineage (rel_type_id int PRIMARY KEY REFERENCES truss.rel_def (rel_type_id) ON DELETE RESTRICT, lineage_category text NOT NULL, identity_profile text NOT NULL, original_identity_bytes bytea NOT NULL, identity_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(original_identity_bytes)) STORED, CONSTRAINT relationship_lineage_category CHECK (lineage_category IN ('authored', 'composition_field')), CONSTRAINT relationship_lineage_profile_nonempty CHECK (length(identity_profile) > 0), CONSTRAINT relationship_lineage_identity_nonempty CHECK (octet_length(original_identity_bytes) > 0)); CREATE INDEX relationship_lineage_route ON truss.relationship_lineage USING btree (identity_sha256, rel_type_id)